                fallback: {
                  color: 'color-purple-700',
                  fontWeight: '600',
                },
              }}
            />
            <Text color="color-gray-500">Custom Fallback</Text>
          </Vertical>

          {/* Gradient */}
          <Vertical alignItems="center" gap={8}>
            <Avatar
              src=""
              fallback="CD"
              views={{
                container: {
                  background:
                    'linear-gradient(135deg, #4F46E5 0%, #9333EA 100%)',
                  borderColor: 'transparent',
                },
                fallback: {
                  color: 'color-white',
                  fontWeight: '600',
                },
              }}
            />
            <Text color="color-gray-500">Gradient</Text>
          </Vertical>
        </Horizontal>
      </View>

      {/* Avatar Groups */}
      <View>
        <Text marginBottom={8} fontWeight="600">
          Avatar Groups
        </Text>
        <Horizontal>
          <View position="relative" width={120} height={48}>
            {sampleImages.map((src, index) => (
              <View
                key={index}
                position="absolute"
                left={`${index * 30}px`}
                zIndex={3 - index}
              >
                <Avatar
                  src={src}
                  size="md"
                  views={{
                    container: {
                      borderWidth: '2px',
                      borderColor: 'white',
                      boxShadow: '0 2px 6px rgba(0, 0, 0, 0.1)',
                    },
                  }}
                />
              </View>
            ))}
          </View>
        </Horizontal>
      </View>

      {/* Interactive Avatars */}
      <View>
        <Text marginBottom={8} fontWeight="600">
          Interactive Avatars
        </Text>
        <Horizontal gap={16} alignItems="center" flexWrap="wrap">
          <Avatar
            src={sampleImages[0]}
            onClick={() => alert('Avatar clicked!')}
            views={{
              container: {
                cursor: 'pointer',
                transition: 'all 0.2s ease',
                _hover: {
                  transform: 'scale(1.1)',
                  boxShadow: '0 4px 12px rgba(0, 0, 0, 0.15)',
                },
              },
            }}
          />
        </Horizontal>
      </View>
    </Vertical>
  );
};

