import React from 'react';
import { Vertical, Text } from 'app-studio';
import { Title } from '@app-studio/components';

/**
 * Examples of Title with alternating highlight text.
 *
 * Contract: `children` is the COMPLETE sentence and must contain
 * `highlightText` verbatim — rotation works by replacing that word inside the
 * sentence (here "changing" in "Our changing solution…"). If the word is
 * absent from `children`, Title warns in dev and rotation is disabled.
 */
export const AlternatingTitle = () => {
  return (
    <Vertical gap={48}>
      <Title
        highlightText="changing"
        alternateHighlightText={[
          'innovative',
          'powerful',
          'flexible',
          'intuitive',
        ]}
        alternateAnimation={true}
        alternateDuration={2000}
        highlightStyle="background"
        highlightColor="theme-primary"
        size="xl"
      >
        Our changing solution for your business
      </Title>

      <Text
        fontSize={14}
        color="color-gray-500"
        marginTop={8}
        marginBottom={24}
      >
        The word &quot;changing&quot; will cycle through &quot;innovative&quot;,
        &quot;powerful&quot;, &quot;flexible&quot;, and &quot;intuitive&quot;
        every 2 seconds
      </Text>

      <Title
        highlightText="rotating"
        alternateHighlightText={['React', 'Vue', 'Angular', 'Svelte']}
        alternateAnimation={true}
        alternateDuration={1500}
        highlightStyle="gradient"
        highlightColor="theme-primary"
        highlightSecondaryColor="theme-secondary"
        highlightAnimate={{
          from: { opacity: 0 },
          to: { opacity: 1 },
          duration: '0.5s',
        }}
        size="xl"
      >
        Build with rotating and other modern frameworks
      </Title>

      <Text
        fontSize={14}
        color="color-gray-500"
        marginTop={8}
        marginBottom={24}
      >
        The word &quot;rotating&quot; will cycle through framework names with a
        gradient style and fade-in animation
      </Text>

      <Title
        highlightText="cycling"
        alternateHighlightText={['fast', 'reliable', 'secure', 'scalable']}
        alternateAnimation={true}
        alternateDuration={3000}
        highlightStyle="glow"
        highlightColor="theme-primary"
        size="xl"
      >
        Our platform is cycling and built for performance
      </Title>

      <Text fontSize={14} color="color-gray-500" marginTop={8}>
        The word &quot;cycling&quot; will cycle through attributes with a glow
        effect every 3 seconds
      </Text>
    </Vertical>
  );
};

import React from 'react';
import { Vertical } from 'app-studio';
import { Title } from '@app-studio/components';

/**
 * Examples of Title with different animation types
 */
export const AnimatedTitle = () => {
  return (
    <Vertical gap={48}>
      <Title
        animate={{
          from: { opacity: 0 },
          to: { opacity: 1 },
          duration: '1.5s',
          iterationCount: '1',
        }}
      >
        Fade In Animation
      </Title>

      <Title
        animate={{
          from: { transform: 'translateX(-100%)' },
          to: { transform: 'translateX(0)' },
          duration: '1s',
          iterationCount: '1',
        }}
      >
        Slide In From Left
      </Title>

      <Title
        animate={{
          from: { transform: 'translateX(100%)' },
          to: { transform: 'translateX(0)' },
          duration: '1s',
          iterationCount: '1',
        }}
      >
        Slide In From Right
      </Title>

      <Title
        animate={{
          from: { transform: 'translateY(-100%)' },
          to: { transform: 'translateY(0)' },
          duration: '1s',
          iterationCount: '1',
        }}
      >
        Slide In From Top
      </Title>

      <Title
        animate={{
          from: { transform: 'translateY(100%)' },
          to: { transform: 'translateY(0)' },
          duration: '1s',
          iterationCount: '1',
        }}
      >
        Slide In From Bottom
      </Title>

      <Title
        animate={{
          from: { clipPath: 'polygon(0 0, 0 0, 0 100%, 0% 100%)' },
          to: { clipPath: 'polygon(0 0, 100% 0, 100% 100%, 0 100%)' },
          duration: '1.5s',
          iterationCount: '1',
        }}
      >
        Reveal Animation
      </Title>

      <Title
        animate={{
          from: { transform: 'translateY(0)' },
          '20%': { transform: 'translateY(-30px)' },
          '40%': { transform: 'translateY(0)' },
          '60%': { transform: 'translateY(-15px)' },
          '80%': { transform: 'translateY(0)' },
          to: { transform: 'translateY(0)' },
          duration: '1s',
          iterationCount: '1',
        }}
      >
        Bounce Animation
      </Title>
    </Vertical>
  );
};

